insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-001','Still Hot — Tokyo Ramen Sprint','seedance_2.0',13,'2.39:1',NULL,NULL,NULL,'missing',5,'A street ramen chef sprints through a neon Tokyo alley at impossible speed, carrying a full bowl of ramen. She vaults crates, leaps rooftops, garnishes the bowl mid-air and slides across a car, then places it gently on the counter in front of a stunned customer: “Still hot.”','prompts/APX-C-001.txt','keep','pass','direct',NULL,'none','high','flagship-ad','Studio; Experience; Menu','photoreal','ALEXA 65mm anamorphic; 2.39:1; film grain; Dolby Vision HDR','teal-orange','mixed','clean','none','none',NULL,'ANCHOR. Impossible action is not a cut. Clip B reference. Re-run at #11, verdict held.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-002','Spice Cosmos','seedance_2.0',15,'9:16',NULL,NULL,NULL,'missing',5,'A pile of desi spices on a rustic table is lifted by a fingertip. The grains float, ignite and burst outward into a universe made entirely of spice — turmeric nebulae, chilli supernovae, cumin planets — before collapsing back into the pile as if nothing happened.','prompts/APX-C-002.txt','keep','pass','direct',NULL,'none','high','craft-piece','Experience; Menu; Studio','macro-stopmotion','100-150mm macro; shallow DOF; volumetric','warm-amber','high-fps-slowmo','clean','transform-render','none',NULL,'ANCHOR. Transformation alone is not a cut — the food stays the subject and returns.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-003','One Bite Fantasy — Dessert World','seedance_2.0',15,'9:16',NULL,NULL,NULL,'missing',5,'A single bite of a chocolate bar fractures reality. The kitchen dissolves into a dessert universe — caramel rivers, cake mountains, cotton-candy clouds — and the character drifts through it, ending on a candy cliff above a glowing sweet landscape.','prompts/APX-C-003.txt','keep','pass','direct',NULL,'none','high','flagship-ad','Studio; Menu; Promotion','stylized-real','8K; soft bloom; volumetric; dreamy DOF','warm-amber','high-fps-slowmo','shaky','transform-render','none','World-dissolve is the make-or-break beat; character consistency inside a full CG world.','ANCHOR. A fantasy world MADE OF THE FOOD keeps, even with no return to reality. Retired the old ''must return'' proxy.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-004','Neon Dumpling Courier','seedance_2.0',15,'9:16',NULL,NULL,NULL,'missing',6,'A courier launches off a noodle-shop awning into a rain-slick rooftop night market, dodging a rival drone swarm with a tower of steaming dumpling baskets. One basket bursts mid-air. He lands at a rooftop table above the city and sets the food down perfectly intact.','prompts/APX-C-004.txt','keep','pass','direct',NULL,'none','high','flagship-ad','Studio; Experience; Menu','photoreal','ultra-detailed steam/reflections; practical comedy timing','neon-magenta','mixed','clean','none','none',NULL,'Ramen''s relative. Sci-fi skin (anti-grav, drones) over a real food-delivery story. Featured food carries it.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-005','Awaken — Espresso Matador','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'A tired man drinks a canned espresso on an Italian cobblestone street, unaware a huge bull is charging behind him. As he drains the can he becomes a matador, dodges the bull with a red cape, then returns to his suit and walks on. The can turns in the light. “Awaken.”','prompts/APX-C-005.txt','keep','pass','direct',NULL,'none','high','flagship-ad','Studio; Promotion; Menu','photoreal','cinematic realism; HDR; real shadows/reflections; 480p specified','warm-amber','mixed','shaky','transform-render; brand-logo-fidelity','real-product-label','480p contradicts ''movie-level quality'' — raise. Two seamless transforms + strict can-label match are the failure points. Watch the oversized bull: comedic-big, not monstrous.','ANCHOR. A person transforming into a HUMAN ROLE (matador) keeps. Becoming a non-human entity cuts.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-006','Alien Donut Heist','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'A tiny overconfident alien courier steals a giant glowing donut from a spaceship kitchen, escaping a guard drone with a jetpack and a pizza-slice parachute. He crashes into a hatch, sticks the landing, and takes an enormous bite.','prompts/APX-C-006.txt','keep','pass','direct',NULL,'none','standard','light-social','Studio; Promotion','3d-animation','hyper-expressive stylised 3D; squash-and-stretch; volumetric fog','neon-magenta','mixed','shaky','none','none',NULL,'Featured food EARNS the home. Donut is the chase object and the payoff; pizza is the parachute. Off-world setting alone does not cut.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-007','Sunset Circuit — Driver''s Day','seedance_2.0',45,'16:9',NULL,NULL,NULL,'missing',15,'A day in the life of a racing driver: waking at seven, breakfast by floor-to-ceiling windows, the drive across the city, the suit zipped, a green GT3 attacking the circuit, the pit-lane walk, a high-five at the garage — and finally, alone at night with a beer, watching it all back.','prompts/APX-C-007.txt','keep','pass','aspirational',NULL,'none','high','mood-piece','Studio; Experience','photoreal','storyboard/previs; 8K; soft bloom; film grain','teal-orange','24fps-cinematic','clean','brand-logo-fidelity','real-brand','Porsche / PUMA marks named. Logo fidelity is a known AI failure and a rights question if it ships.','ANCHOR. Opened the ASPIRATIONAL route. Premium lifestyle earns a home with no featured dish. Food (eggs, beer) is incidental and that is fine.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-008','Rooftop Extraction','seedance_2.0',15,'2.39:1',NULL,NULL,NULL,'missing',8,'A woman in a trench coat runs a rain-slicked rooftop forty storeys above a neon city, pursued by armed operatives. She swings off the ledge into freefall between two skyscrapers, crashes through a skylight, rolls, and disappears into a stairwell without breaking stride.','prompts/APX-C-008.txt','keep','pass','aspirational',NULL,'none','high','mood-piece','Studio','photoreal','8K; anamorphic 2.39:1; crushed blacks; Dolby Vision HDR','teal-orange','mixed','clean','none','none',NULL,'ANCHOR. Widened the aspirational route — action/thriller intensity qualifies, not just luxury leisure. No food, no venue, still keeps.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-009','Main Character Energy','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'An ordinary day shot like a film trailer: the alarm, the coffee, the commute, the meeting, the rain on the pavement — every mundane beat given weight and slow motion, ending on a rooftop above the skyline at sunset.','prompts/APX-C-009.txt','keep','pass','aspirational',NULL,'none','low','mood-piece','Studio','photoreal','ultra cinematic realism; lens flares; film-grade grade','teal-orange','mixed','shaky','none','none','Weak, generic prompt. Likely nobody''s favourite. Real-world and brand-safe, so it holds a place in the library. Upgrade at intake via the motion/emotion script if a client engages.','Tests the ASPIRATIONAL FLOOR — and there isn''t one. Keeps on mood alone. Tagged low-distinctiveness so it never leads a selection. Re-run at #25, verdict held.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-010','The Storm That Is Approaching','seedance_2.0',55,'16:9',NULL,NULL,'https://x.com/john87445528/status/2036409868710457682','missing',6,'A bionic warrior escapes a drowned city, strikes a rescue beacon and tears open a portal into blazing noon. She lands in an ancient Eastern food market, sprints between fruit stalls and hanging spice, then turns to face what followed her into the alley.','prompts/APX-C-010.txt','keep','pass','direct',NULL,'UNRESOLVED','high','flagship-ad','Studio; Venue; Event','photoreal','4K cinematic realism; handheld throughout; hyperreal water physics','mixed','mixed','clean','character-consistency','none','Carries genuinely dark content (zombies, blood). Kept because the food market is a real home and the clip is strong — but its status depends on the Halloween/occasion rule, which is NOT SET.','ANCHOR (paired with the volcanic cut). Dark surface + real food home = keep. Dark surface + no home = cut. Darkness was never the trigger; the home is.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-011','Eid Mubarak — Desert Light','seedance_2.0',40,'16:9',NULL,NULL,NULL,'missing',9,'Dawn over the dunes as a family prepares for Eid. Robes and jewellery, a walk beside the camels, a feast of dates and tea laid on carpets, greetings under lanterns, prayer at the desert mosque, fireworks over the sand, and a crescent moon above the dunes.','prompts/APX-C-011.txt','keep','pass','both',NULL,'eid','high','cultural-moment','Event; International; Menu; Studio','photoreal','ultra-realistic; soft film grain; 4K','golden-hour','24fps-cinematic','clean','on-screen-text','none','Arabic calligraphy title card is a known AI text-render failure. Overlay in post.','First cultural-moment keeper. Both routes open: featured Eid feast (direct) + traditional luxury aesthetic (aspirational).',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-012','Wuhan — River City','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'The camera pushes through the steam of a bowl of hot dry noodles and cuts hard to the Yangtze. A dragon dance winds through the old streets, dawn light falls through the eaves of the Yellow Crane Tower, and the city lights ignite along both banks at night.','prompts/APX-C-012.txt','keep','pass','both',NULL,'none','high','destination-showcase','Venue; International; Studio; Experience','photoreal','8K; one-take logic; FPV drone','mixed','24fps-cinematic','clean','none','none',NULL,'Destination showcase. Featured noodles = direct home; place-as-destination = aspirational. Impossible FPV camera is cinematography, not fantasy.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-013','Guangzhou — Teahouse to Tower','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'Steam rises off dim sum in an old teahouse and the city answers — a lion dance leaping through the lanes, dawn on the carved timber of the ancestral hall, and a headlong FPV climb around the Canton Tower as the Pearl River burns with neon.','prompts/APX-C-013.txt','keep','pass','both',NULL,'none','high','destination-showcase','Venue; International; Studio; Experience','photoreal','8K; one-take logic; FPV drone','mixed','24fps-cinematic','clean','none','none',NULL,'Sibling of Wuhan (same template, city+dish swapped). Identical verdict — gate is stable across a template family. TEMPLATE-FAMILY: china-city-portrait.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-014','Beach BBQ — Signature Sauce','seedance_2.0',60,'16:9',NULL,NULL,NULL,'missing',4,'Golden hour on a tropical beach. A woman lays out fresh ingredients, pours a glossy sweet-soy sauce over chicken skewers, brushes each one, and grills them over open flame. She sits with the sea behind her and takes the first bite. The sauce pouch rests on the board among the skewers.','prompts/APX-C-014.txt','keep','pass','both',NULL,'none','high','food-cm','Studio; Promotion; Menu; International','photoreal','8K realism; shallow DOF; premium food-CM styling','golden-hour','mixed','clean','brand-logo-fidelity; character-consistency','real-product-label','Exact sauce label across 4 parts + one consistent face across 4 generations. Both are standard failure points.','Purest ''this is the product'' sample. Direct food home at full strength. Food-ad enthusiasm is genre-honest — does NOT trip the authenticity gate.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-015','The Pour — Latte Art','seedance_2.0',10,'16:9',NULL,NULL,NULL,'missing',5,'Morning light through a café window. Espresso falls like molten lava under thick golden crema, milk spins to silk in the pitcher, and a galloping horse forms on the surface of the cup. The focus shifts from the art to the barista''s quiet satisfaction.','prompts/APX-C-015.txt','keep','pass','direct',NULL,'none','high','craft-piece','Experience; Menu; Venue','photoreal','85mm; shallow DOF; volumetric light; ASMR sound design','warm-amber','24fps-cinematic','clean','liquid-sim','none','Crema texture and the horse pattern forming cleanly are the two beats that decide the clip.','Strongest form of the direct home: food + venue + staff all in frame. Model of a disciplined shot-list prompt.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-016','POV: Your Cat Runs a Michelin Restaurant','seedance_2.0',15,'9:16',NULL,NULL,NULL,'missing',5,'An orange cat in a chef''s hat runs a Michelin kitchen at peak service — chopping, flipping pans, salting like a celebrity chef, silently screaming at the humans. It pauses, stares down the camera, then plates a perfect pasta while the dining room stands and weeps.','prompts/APX-C-016.txt','keep','pass','direct',NULL,'none','high','meme-comedy','Studio; Experience','stylized-real','Pixar-quality realism; realistic fur physics; meme pacing','warm-amber','mixed','shaky','animal-dexterity; on-screen-text','real-person-likeness','Cat performing fine human motor tasks is the hardest ask in the set. Meme subtitles render unreliably — overlay in post. ''Gordon Ramsay energy'' is referenced, not depicted; do not name or show him.','ANCHOR. An animal in a HUMAN HOSPITALITY ROLE keeps — the inverse of a person becoming a non-human being. Honest absurd comedy is not the fake-contrived cut.',true) on conflict (clip_id) do nothing;
insert into clips (clip_id,title,generator,runtime_s,aspect_ratio,video_url,thumbnail_url,source_url,asset_status,shot_count,summary,source_prompt_file,verdict,step1_grounded_brand_safe,home_route,cut_reason,occasion_context,distinctiveness,register,product_fit,realism_level,render_stack,grade,motion_feel,prompt_health,risk_flags,ip_flags,fix_note,calibration_note,is_demo_seed) values ('APX-C-017','Chef vs Raccoon','seedance_2.0',15,'16:9',NULL,NULL,NULL,'missing',5,'A cheerful chef carries a giant pepperoni pizza across a sunny backyard. A raccoon challenges him for it. After a lunge, a flip and a furious tug-of-war, the box snaps and the pizza lands squarely on a sleeping bulldog''s head. The bulldog opens one eye.','prompts/APX-C-017.txt','keep','pass','direct',NULL,'none','standard','light-social','Studio; Menu','3d-animation','3D cartoon; dynamic crane/orbit/whip-pan','golden-hour','mixed','clean','none','none',NULL,'Reinforces the animal-around-food keep and the honest-comedy scope guard. Slotted in with no new rule needed.',true) on conflict (clip_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-001-1','APX-C-001',1,0.0,2.5,2.5,'Extreme low-angle tracking shot — a hyper-focused street female food chef sprints at impossible speed through a neon-lit Tokyo alley, clutching a steaming bowl of ramen. Crisp apron flapping, sleeves rolled, sneakers splashing through puddles. Camera shakes aggressively behind them. Steam trails like smoke. Neon signs streak across frame.','A street chef sprints flat-out through a neon alley, holding a steaming bowl of ramen level as she runs. Puddles spray, steam trails behind her.',NULL,'chef','sprinting','ramen','hero','neon Tokyo alley','wide','low','tracking','real-time','neon practicals','steam','footfalls; splashing',NULL,'intense','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-001-2','APX-C-001',2,2.6,5.0,2.4,'Whip-pan — they shoulder-check a stack of plastic crates. TIME REMAP: slow-motion chaos — vegetables, bowls, and chopsticks explode into the air. Broth ripples in perfect cinematic detail without spilling. They tilt the bowl mid-run, saving every drop.','She shoulder-charges a stack of crates. Vegetables, bowls and chopsticks burst into the air in slow motion while the broth ripples but never spills.',NULL,'chef','sprinting','broth; vegetables','hero','neon Tokyo alley','medium','eye','whip-pan','time-remap','neon practicals','particles','crate clatter',NULL,'intense','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-001-3','APX-C-001',3,5.1,7.5,2.4,'Drone shot — they leap across narrow alley gaps between buildings. SLOW MOTION: steam spirals upward into neon light. A cat jumps out of the way. Laundry lines ripple. They casually garnish the ramen mid-air with one hand — flawless precision.','She leaps between rooftops. Steam spirals into the neon. Mid-air, one hand garnishes the bowl without looking.',NULL,'chef','leaping; garnishing','ramen','hero','alley rooftops','wide','high','drone','slow-mo','neon practicals','steam','wind',NULL,'intense','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-001-4','APX-C-001',4,7.6,10.0,2.4,'360° orbital shot — they slide across the hood of a parked car, spin, land clean. One sandal nearly slips off but is caught mid-motion. They adjust grip on the bowl, completely composed.','She slides across the hood of a parked car, spins, lands clean, and re-grips the bowl without breaking composure.',NULL,'chef','sliding','ramen','featured','street / parked car','medium','eye','orbit','real-time','neon practicals','none','metal slide',NULL,'intense','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-001-5','APX-C-001',5,10.1,13.0,2.9,'First-person POV — a small ramen shop door rushes forward. SMASH CUT: door slams open. Steam floods the frame. They step in, perfectly calm now. Place the bowl gently on the counter. Slow push-in. Low-angle shot. They look at the customer.','The shop door bursts open and steam floods the room. Calm now, she sets the bowl gently on the counter and looks at the customer. The customer says nothing.',NULL,'chef','serving','ramen','hero','ramen shop interior','cu','low','pov; push-in','real-time','warm interior','steam','door slam; ceramic','Still hot.','calm','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-002-1','APX-C-002',1,0.0,3.0,3.0,'Scene opens on a rustic wooden table bathed in warm sunrise light. A small pile of mixed desi spices (turmeric, chili flakes, cumin, cardamom) sits still in extreme macro close-up. Dust particles gently float in visible light rays.','A small pile of turmeric, chilli, cumin and cardamom rests on a rustic wooden table in the first light of morning. Dust drifts through the beams.',NULL,'none','none','spices','hero','rustic table','ecu','eye','static','real-time','warm sunrise; volumetric','particles','room tone',NULL,'calm','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-002-2','APX-C-002',2,3.0,7.0,4.0,'A human finger slowly enters frame and pinches the spice mix. As the spices are lifted, the grains begin to defy gravity and float in slow motion. Each particle subtly starts glowing with warm tones (gold, red, amber).','A fingertip pinches the spice. The grains lift, hang in the air, and begin to glow gold and amber.',NULL,'none','pouring','spices','hero','rustic table','ecu','eye','static','slow-mo','warm sunrise','particles','tonal hum',NULL,'awe','yes',NULL) on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-002-3','APX-C-002',3,7.0,11.0,4.0,'The spices suddenly burst outward in slow motion. Turmeric transforms into glowing golden nebula clouds, chili flakes become fiery red supernova explosions, cumin seeds turn into tiny orbiting planets. The camera begins a slow orbital rotation around the expanding structure.','The spice bursts outward. Turmeric becomes a golden nebula, chilli flakes ignite like supernovae, cumin seeds orbit as tiny planets.',NULL,'none','none','spices','hero','cosmos-of-spice','wide','eye','orbit','slow-mo','self-lit','particles; energy','bass whoosh; crackle',NULL,'awe','partial','transform render') on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-002-4','APX-C-002',4,11.0,14.0,3.0,'The frame fully transforms into a cosmic universe made entirely of spices. Swirling galaxies form from spice textures, stars sparkle like salt crystals, and nebulae flow like colored powder clouds. The camera slowly pulls back to reveal the full universe scale.','The frame becomes a universe made entirely of spice — galaxies of powder, stars like salt crystals — revealed in full as the camera pulls back.',NULL,'none','none','spices','hero','cosmos-of-spice','extreme-wide','eye','pull-back','slow-mo','self-lit','particles','deep hum',NULL,'awe','partial','transform render') on conflict (shot_id) do nothing;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,shot_deeplink,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,audio_sfx,dialogue,mood,liftable,shot_risk) values ('APX-S-002-5','APX-C-002',5,14.0,15.0,1.0,'The entire cosmic structure collapses smoothly back into the original spice pile. The finger re-enters the frame, resetting everything as if nothing happened, creating a seamless loop.','The universe collapses back into the spice pile. The finger returns. Nothing ever happened.',NULL,'none','none','spices','hero','rustic table','ecu','eye','static','real-time','warm sunrise','particles','time-reset tick',NULL,'calm','yes',NULL) on conflict (shot_id) do nothing;
