, source_url=excluded.source_url, verbatim_prompt=excluded.verbatim_prompt, asset_status=excluded.asset_status, shot_count=excluded.shot_count, summary=excluded.summary, verdict=excluded.verdict, step1_grounded_brand_safe=excluded.step1_grounded_brand_safe, home_route=excluded.home_route, distinctiveness=excluded.distinctiveness, register=excluded.register, realism_level=excluded.realism_level, render_stack=excluded.render_stack, grade=excluded.grade, motion_feel=excluded.motion_feel, ip_flags=excluded.ip_flags, gate_confidence=excluded.gate_confidence, gate_notes=excluded.gate_notes, is_demo_seed=excluded.is_demo_seed;
